import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.Cq0X4QeM.js";const u=JSON.parse('{"title":"HTTP parameter pollution","description":"","frontmatter":{"authors":"KenjiEndo15, ShutdownRepo, Fantabc","category":"web"},"headers":[],"relativePath":"web/inputs/http-parameter-pollution.md","filePath":"web/inputs/http-parameter-pollution.md"}'),o={name:"web/inputs/http-parameter-pollution.md"};function i(n,e,h,l,p,d){return a(),r("div",null,e[0]||(e[0]=[s('<h1 id="http-parameter-pollution" tabindex="-1">HTTP parameter pollution <a class="header-anchor" href="#http-parameter-pollution" aria-label="Permalink to &quot;HTTP parameter pollution&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>A query parameter allows a client to refine researches on a website. It is composed of a key (the parameter name) and a value (what we are requesting).</p><p>With parameter pollution, we enter a query parameter with the same key multiple times. For example, we could have <code>$URL?username=X&amp;username=Y</code>, but which one does a web server choose?<br> In fact, each web servers adopt different behaviors: some of them choose the first parameter, the second parameter, or every parameter.</p><p>This attack could allow an attacker to bypass input validation and WAFs rules, manipulate, access, or retrieve hidden information.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><h3 id="before-the-attack" tabindex="-1">Before the attack <a class="header-anchor" href="#before-the-attack" aria-label="Permalink to &quot;Before the attack&quot;">​</a></h3><p><a href="https://github.com/s0md3v/Arjun" target="_blank" rel="noreferrer">Arjun</a> can be used to find HTTP parameters in a website.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arjun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/endpoint</span></span></code></pre></div><div class="tip custom-block"><p>It&#39;s possible to specify a delay between requests and handle rate limits.<br> Check out the <a href="https://github.com/s0md3v/Arjun/wiki/Usage#scan-a-single-url" target="_blank" rel="noreferrer">GitHub page</a>.</p></div><p>After discovering a few HTTP parameters, one should know the server&#39;s behavior when presented with the same key multiple times.</p><ol><li><p>When presented with a query string in a URL, check the response the server gives with one key.</p><p><code>http://example.com/search=result1</code></p></li><li><p>Repeat the first step with another value (make sure to check the response).</p><p><code>http://example.com/search=result2</code></p></li><li><p>Once you are able to identify what kind of response the server returns for each value, try to combine both and see which one is used.</p><p><code>http://example.com/page?search=result1&amp;search=result2</code></p></li></ol><p>*The result could be a combination of both, giving a new response.</p><p>The payload that would be used to conduct a HPP will depend on the browser&#39;s behavior (found previously).</p><h3 id="server-parameter-handling-order" tabindex="-1">Server parameter handling order <a class="header-anchor" href="#server-parameter-handling-order" aria-label="Permalink to &quot;Server parameter handling order&quot;">​</a></h3><p>Depending on the web server, a parameter may not be processed in the same way. Here&#39;s a list of the parameters used by some web servers.</p><table tabindex="0"><thead><tr><th>Server</th><th>Parameter</th></tr></thead><tbody><tr><td>ASP.NET / IIS</td><td>All (array of values)</td></tr><tr><td>ASP / IIS</td><td>All (array of values)</td></tr><tr><td>PHP / Apache</td><td>Last</td></tr><tr><td>JSP, Servlet / Tomcat</td><td>First</td></tr><tr><td>Perl CGI / Apache</td><td>First</td></tr><tr><td>Python Flask</td><td>First</td></tr><tr><td>Python Django</td><td>Last</td></tr><tr><td>NodeJS</td><td>All (array of values)</td></tr><tr><td>Ruby on Rails</td><td>Last</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><details class="details custom-block"><summary>Google CTF Challenge</summary><p>From the <strong>Under Construction</strong> web challenge of the 2023 Google CTF.</p><p>This challenge had 2 web servers : a <strong>Flask</strong> one and a <strong>PHP (Apache)</strong> one. When reaching the main page, a register form asked to choose a username, a password and a tier. The goal was to get the <strong>&quot;Gold tier&quot;</strong>. When registering, the first web server (Flask) checked the tier wasn&#39;t the &quot;Gold tier&quot; that only the CEO had access to. If the check passed, it then forwarded the HTTP request to the PHP server that stored the registration in the database.</p><p>To bypass the check, the user had to abuse a parameter pollution. As seen in the table above, Python Flask performs the check on the first parameter but PHP (Apache) stores the last parameter. This was the URL to trigger to get the much-desired <strong>Gold tier</strong> :</p><blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;url&gt;/signup?username=X&amp;password=Y&amp;tier=blue&amp;tier=gold</span></span></code></pre></div></blockquote></details><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><a href="https://owasp.org/www-project-web-security-testing-guide/latest/4-Web_Application_Security_Testing/07-Input_Validation_Testing/04-Testing_for_HTTP_Parameter_Pollution" target="_blank" rel="noreferrer">https://owasp.org/www-project-web-security-testing-guide/latest/4-Web_Application_Security_Testing/07-Input_Validation_Testing/04-Testing_for_HTTP_Parameter_Pollution</a></p><p><a href="https://github.com/swisskyrepo/PayloadsAllTheThings/tree/master/HTTP%20Parameter%20Pollution" target="_blank" rel="noreferrer">https://github.com/swisskyrepo/PayloadsAllTheThings/tree/master/HTTP%20Parameter%20Pollution</a></p>',22)]))}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
